import json

facts = {
    ("movie_year", "chihuahua", 2010),
    ("card_color", "ostrich", "indigo"),
    ("profession", "ostrich", "public relations specialist"),
    ("friends", "shark", 16),
    ("invests", "shark", "fangtooth"),
}
proof = {fact: ("given", ()) for fact in facts}

facebook_founded_year = 2004
rainbow_colors = {"red", "orange", "yellow", "green", "blue", "indigo", "violet"}

def add(fact, reason, premises):
    if fact not in facts:
        facts.add(fact)
        proof[fact] = (reason, tuple(premises))
        return True
    return False

for fact in list(facts):
    if fact[0] == "movie_year" and fact[2] > facebook_founded_year:
        add(("movie_after_facebook", fact[1]), "year comparison", [fact])
    elif fact[0] == "card_color" and fact[2] in rainbow_colors:
        add(("rainbow_card", fact[1]), "rainbow membership", [fact])
    elif fact[0] == "friends" and fact[2] > 10:
        add(("more_than_ten_friends", fact[1]), "friend-count comparison", [fact])

animals = {"chihuahua", "ostrich", "shark"}
rules = [
    ("Rule1", [("works_in", "ostrich", "education")],
     ("not_invests", "ostrich", "shark")),
    ("Rule2", [("movie_after_facebook", "chihuahua")],
     ("hides_cards", "chihuahua", "shark")),
    ("Rule5", [("hides_cards", "chihuahua", "shark"),
               ("not_invests", "ostrich", "shark")],
     ("disarms", "shark", "zebra")),
    ("Rule6", [("rainbow_card", "ostrich")],
     ("not_invests", "ostrich", "shark")),
    ("Rule7", [("younger_than_18_months", "shark")],
     ("acquires_photo", "shark", "swallow")),
    ("Rule9", [("more_than_ten_friends", "shark")],
     ("acquires_photo", "shark", "swallow")),
]
for animal in sorted(animals):
    rules.extend([
        ("Rule3", [("smiles", animal, "basenji"),
                   ("disarms", animal, "zebra")],
         ("not_dances", animal, "dugong")),
        ("Rule4", [("invests", animal, "fangtooth")],
         ("pays", animal, "badger")),
        ("Rule8", [("pays", animal, "badger")],
         ("smiles", animal, "basenji")),
    ])

changed = True
while changed:
    changed = False
    for name, premises, conclusion in rules:
        if all(p in facts for p in premises):
            changed |= add(conclusion, name, premises)

positive = ("dances", "shark", "dugong")
negative = ("not_dances", "shark", "dugong")
if positive in facts and negative in facts:
    print("UNSUPPORTED")
else:
    answer = (
        "disproved" if negative in facts
        else "proved" if positive in facts
        else "unknown"
    )
    evidence = []
    visited = set()

    def explain(fact):
        if fact in visited:
            return
        visited.add(fact)
        reason, premises = proof[fact]
        for premise in premises:
            explain(premise)
        evidence.append({"fact": list(fact), "source": reason})

    if negative in facts:
        explain(negative)
    elif positive in facts:
        explain(positive)

    print(json.dumps(
        {"final_answer": answer, "evidence": evidence},
        separators=(",", ":")
    ))
